static constexpr Sprite kEmptySprite = {0,0,nullptr,0,nullptr,0};
inline const Sprite &descriptor(Asset asset) {
  switch (asset) {
    case Asset::Nozzle: return kNozzle;
    case Asset::Bed: return kBed;
    case Asset::Chamber: return kChamber;
    case Asset::Print: return kPrint;
    case Asset::AMS: return kAMS;
    case Asset::Details: return kDetails;
    case Asset::Settings: return kSettings;
    case Asset::Spool: return kSpool;
    case Asset::Model: return kModel;
    case Asset::Plate: return kPlate;
    case Asset::Head: return kHead;
    case Asset::Clock: return kClock;
    case Asset::Weather: return kWeather;
    case Asset::Network: return kNetwork;
    case Asset::Check: return kCheck;
    case Asset::Pause: return kPause;
    case Asset::Alert: return kAlert;
    case Asset::EmptySlot: return kEmptySlot;
    case Asset::UnknownData: return kUnknownData;
    case Asset::Printer: return kPrinter;
    case Asset::Fan: return kFan;
    default: return kEmptySprite;
  }
}
